INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '现期比重', 'kp-xingce-data-proportion-current', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "现期比重"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "某部分数值占整体总数值的比例。资料分析三大命脉之首。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“2023年某指标占总体的比重为多少？” 没有任何时间推移，直接用当期数据。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "比重 = \\frac{部分量}{整体量} = \\frac{A}{B}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干找到'占'或'其中'] --> B[定位分子: 占字前面的是部分]\nB --> C[定位分母: 占字后面的是整体]\nC --> D[列出式子: A / B]\nD --> E[观察选项差距]\nE --> F[采用截位直除法估算得出比重]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年全国货物进出口 41.76 万亿，其中出口 23.77 万亿。求出口占进出口总额的比重？选项：A. 45.2% B. 50.1% C. 56.9% D. 61.2%"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "找分子分母：分子是出口(23.77)，分母是总额(41.76)。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "列式：23.77 ÷ 41.76。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "观察选项：首位有4,5,5,6，差距较大。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "截位估算：分母截三位为 418。分子 2377。2377 ÷ 418。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "首位直除：商首位为 5 (余287)。第二位商 6。结果约为 56%。选 C。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "谁占谁搞反：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "材料说“高新技术企业中，外资占 30%”，去材料找数据时，别把“高新技术”放到分子上！永远记住“占”字前面的是分子，“占”字后面的是分母。除反了，选项里一定有坑等你。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "重点训练在包含各种“其中”的复杂段落里，迅速拎出“母集”和“子集”的能力。"}]}]}$$ AS jsonb), NULL, '现期比重的核心考点与实战推导。', category_node.id, CAST('["资料分析", "现期比重"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_proportion_current", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
